        self.graph[start].append(goal)
        if not self.directed:
            self.graph[goal].append(start)

def find_path(graph, start, goal):
    if start not in graph.graph or goal not in graph.graph:
        return None

    if start == goal:
        return [start]

    explored = set()
    queue = [[start]]

    while queue:
        path = queue.pop(0)
        node = path[-1]
        if node not in explored:
            neighbours = graph.graph[node]
            for neighbour in neighbours:
                new_path = list(path)
                new_path.append(neighbour)
                queue.append(new_path)
                if neighbour == goal:
                    return new_path
            explored.add(node)
    return None

