def find_path(graph, start, goal):
    visited = set()  # Set to keep track of visited nodes
    path = None  # To store the final path

    from collections import deque  # Use deque for efficient enqueue and dequeue operations
    from copy import deepcopy  # Use deepcopy for constructing paths without modifying the original graph

    queue = deque([(start, [start])])  # Initialize a queue with a tuple of (current node, path)

    while queue:
        (current_node, path) = queue.popleft()  # Get the current node and its path from the queue

        if current_node not in visited:
            visited.add(current_node)  # Mark the current node as visited

            if current_node == goal:
                path = path  # If the goal is reached, we have found the path
            else:
                # For each neighbor of the current node, add it to the queue with the current path extended by the neighbor
                for neighbor in graph.get(current_node, []):
                    if neighbor not in visited:
                        queue.append((neighbor, deepcopy(path) + [neighbor]))

    return path
